-- 增补 SG 实战情境与自编练习题。所有新增题均标记 generated/authored，不冒充官方真题。
INSERT OR IGNORE INTO practical_scenarios
(id, track_id, title, category, difficulty, situation, task, options_json, best_option, scoring_json, explanation, source_type)
VALUES
('sg-scenario-mfa-002','exam-sg','处理 MFA 疑似疲劳轰炸','认证与访问控制','intermediate',
 '员工连续收到自己没有发起的登录批准通知，随后有人打电话自称服务台，要求批准一次请求以便“停止通知”。',
 '最合适的处置是什么？',
 '[{"id":"a","text":"批准一次请求，然后立即改密码"},{"id":"b","text":"拒绝未发起的请求，通过已知渠道报告服务台并按流程保护账号"},{"id":"c","text":"把验证码发给来电者"},{"id":"d","text":"关闭所有安全通知"}]',
 'b','{"a":20,"b":100,"c":0,"d":0}',
 '未发起的 MFA 请求可能表示密码已泄露。拒绝请求，不向来电者提供验证码，并通过可信渠道报告、检查账号和会话。',
 'authored'),
('sg-scenario-backup-002','exam-sg','确认备份真的可恢复','业务连续性','standard',
 '团队每晚都收到备份成功通知，但从未尝试恢复。审计发现关键系统的恢复时间目标为四小时。',
 '下一步哪项最能验证备份能力？',
 '[{"id":"a","text":"只要备份任务显示成功就认定合格"},{"id":"b","text":"删除旧备份节省空间"},{"id":"c","text":"按计划进行恢复演练，记录恢复耗时、数据完整性并与目标比较"},{"id":"d","text":"把所有备份放在同一台生产服务器上"}]',
 'c','{"a":20,"b":0,"c":100,"d":0}',
 '备份成功不等于可恢复。应定期演练恢复，验证数据完整性、可用性和实际恢复时间，并确认满足 RTO/RPO。',
 'authored'),
('sg-scenario-vendor-001','exam-sg','供应商要求开放远程访问','供应链安全','intermediate',
 '供应商要求为排查问题开放生产系统的永久管理员远程访问权限，但合同与审批记录中没有此项安排。',
 '你应该怎么做？',
 '[{"id":"a","text":"先开放，之后再补审批"},{"id":"b","text":"创建共享管理员账号供供应商使用"},{"id":"c","text":"暂停授权，按供应商接入与风险审批流程确认范围、期限、身份验证和日志要求"},{"id":"d","text":"把生产数据库导出发给供应商"}]',
 'c','{"a":0,"b":0,"c":100,"d":0}',
 '第三方访问应经过授权和风险评估，限制权限与期限，使用可追踪的个人身份、强认证和日志，不能先开权限再补手续。',
 'authored'),
('sg-scenario-personal-data-001','exam-sg','误发含个人信息的邮件','个人信息保护','standard',
 '同事发现自己把含客户个人信息的文件发给了错误的外部收件人。收件人尚未回复。',
 '哪项行动最恰当？',
 '[{"id":"a","text":"假装没有发生，避免影响评价"},{"id":"b","text":"按组织规定立即报告，保留相关记录并由负责人评估通知、撤回和后续措施"},{"id":"c","text":"删除发件箱中的邮件就算处理完成"},{"id":"d","text":"公开收件人姓名以警示他人"}]',
 'b','{"a":0,"b":100,"c":10,"d":0}',
 '误发送可能构成个人信息事件。及时报告并保全证据，由责任部门评估影响、联系收件人、采取限制措施及是否需要进一步通知。',
 'authored'),
('sg-scenario-logs-001','exam-sg','日志中出现异常管理员操作','日志与监控','standard',
 '审计日志显示管理员账号在非工作时间修改权限，但该管理员说自己没有操作。',
 '调查时优先做什么？',
 '[{"id":"a","text":"先清理日志以免占用空间"},{"id":"b","text":"在没有调查前直接删除管理员账号和全部数据"},{"id":"c","text":"保全日志和相关证据，按事件流程核实身份、会话和变更记录，并采取授权的遏制措施"},{"id":"d","text":"把日志发到公开论坛请人分析"}]',
 'c','{"a":0,"b":10,"c":100,"d":0}',
 '日志是调查证据，应限制访问并保全。通过可信渠道核实身份和会话，按流程评估影响与遏制措施，避免破坏证据或泄露信息。',
 'authored'),
('sg-scenario-phishing-002','exam-sg','员工已经输入钓鱼网站密码','事件响应','intermediate',
 '员工承认刚刚在可疑网页输入了公司密码，但尚不清楚攻击者是否登录成功。',
 '最适当的下一步是什么？',
 '[{"id":"a","text":"等待是否出现损失再处理"},{"id":"b","text":"立即按事件流程报告，通过可信渠道更改凭据并撤销可疑会话，检查 MFA 与登录日志"},{"id":"c","text":"把密码发给安全人员确认"},{"id":"d","text":"只清空浏览器历史记录"}]',
 'b','{"a":0,"b":100,"c":0,"d":10}',
 '凭据可能已泄露，应立即报告并通过可信渠道更改密码、撤销会话、检查异常登录与 MFA 设置，同时保留事件信息。',
 'authored'),
('sg-scenario-patch-001','exam-sg','紧急修补高危漏洞','漏洞管理','intermediate',
 '供应商发布了影响互联网暴露系统的高危漏洞修补程序，但组织的变更流程要求测试和审批。',
 '最合适的做法是什么？',
 '[{"id":"a","text":"不论风险都等待下个月例行发布"},{"id":"b","text":"直接绕过所有记录安装补丁"},{"id":"c","text":"启动紧急变更流程，评估暴露与影响，进行适当验证、审批、备份和回滚准备并记录"},{"id":"d","text":"公开漏洞细节和未修补服务器地址"}]',
 'c','{"a":0,"b":35,"c":100,"d":0}',
 '高危漏洞需要快速处置，但应通过紧急变更流程控制风险，记录评估、验证、审批、实施与回滚措施。',
 'authored'),
('sg-scenario-access-review-001','exam-sg','离职人员仍有系统权限','访问控制','standard',
 '人事通知一名员工已离职，但系统中仍存在该员工的 VPN 和业务应用账号。',
 '应优先采取什么措施？',
 '[{"id":"a","text":"等账号自然过期"},{"id":"b","text":"按离职流程及时停用访问权限，并核查资产归还、共享凭据和相关日志"},{"id":"c","text":"把账号交给新员工继续使用"},{"id":"d","text":"只删除邮箱，不处理其他系统"}]',
 'b','{"a":0,"b":100,"c":0,"d":20}',
 '离职或职责变更应触发及时的权限撤销与复核，避免遗留账号被滥用，并核对设备、密钥和其他访问途径。',
 'authored');

INSERT OR IGNORE INTO questions
(id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language)
VALUES
('sg-practice-0006','exam-sg','リスクマネジメント','standard','single_choice','リスク対応の「低減」に該当するものはどれか。',
'[{"id":"a","text":"リスクのある業務を中止する"},{"id":"b","text":"対策を実施して発生可能性や影響を小さくする"},{"id":"c","text":"保険契約などで損失を第三者に移転する"},{"id":"d","text":"リスクを把握したうえで対策せず受容する"}]','"b"','正解は B。低減は対策によってリスクの発生可能性または影響を小さくすること。A は回避、C は移転、D は受容に当たる。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0007','exam-sg','暗号化とハッシュ','standard','single_choice','パスワードを保存するときの説明として最も適切なものはどれか。',
'[{"id":"a","text":"復号できる暗号化だけを行う"},{"id":"b","text":"すべての利用者に同じソルトを使う"},{"id":"c","text":"個別のソルトとパスワード向けハッシュ方式を使う"},{"id":"d","text":"パスワードをログに記録する"}]','"c"','正解は C。パスワード保存には Argon2id、scrypt、bcrypt などの専用方式を使い、利用者ごとのソルトを適用する。暗号化は復号可能であり、単純な高速ハッシュだけも不適切。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0008','exam-sg','ネットワークセキュリティ','standard','single_choice','TLS を利用する主な目的として最も適切なものはどれか。',
'[{"id":"a","text":"通信経路上の盗聴や改ざんのリスクを低減する"},{"id":"b","text":"すべての端末のマルウェアを自動削除する"},{"id":"c","text":"データベースのバックアップを自動作成する"},{"id":"d","text":"利用者の業務権限を自動決定する"}]','"a"','正解は A。TLS は通信の暗号化と完全性保護、証明書による相手の認証に利用される。マルウェア対策、バックアップ、認可とは役割が異なる。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0009','exam-sg','アクセス制御','standard','single_choice','最小権限の原則に最も合致する運用はどれか。',
'[{"id":"a","text":"全社員に管理者権限を付与する"},{"id":"b","text":"業務に必要な範囲だけ権限を付与し、定期的に見直す"},{"id":"c","text":"複数人で同じアカウントを共有する"},{"id":"d","text":"退職者のアカウントを残す"}]','"b"','正解は B。必要最小限の権限を付与し、職務変更や退職時に見直す。共有アカウントや不要な権限は追跡可能性と安全性を損なう。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0010','exam-sg','インシデント対応','standard','single_choice','情報漏えいの疑いがある場合の対応として最も適切なものはどれか。',
'[{"id":"a","text":"ログを削除してから報告する"},{"id":"b","text":"SNS で詳細を公開する"},{"id":"c","text":"定められた手順で報告し、証拠を保全する"},{"id":"d","text":"何も記録せず通常業務を続ける"}]','"c"','正解は C。報告手順に従い、ログや関連記録を保全する。証拠削除や無断公開は調査と被害対応を妨げる。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0011','exam-sg','事業継続','standard','single_choice','RTO の説明として最も適切なものはどれか。',
'[{"id":"a","text":"許容できるデータ損失の時間幅"},{"id":"b","text":"障害発生後にサービスを復旧する目標時間"},{"id":"c","text":"暗号鍵の有効期間"},{"id":"d","text":"監査ログの保存期間"}]','"b"','正解は B。RTO は目標復旧時間。RPO は障害時に許容するデータ損失を時間で表した目標であり、両者を混同しない。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0012','exam-sg','事業継続','standard','single_choice','RPO が 1 時間の場合、最も適切な説明はどれか。',
'[{"id":"a","text":"必ず 1 時間以内に全サービスを復旧する"},{"id":"b","text":"障害時に失ってよいデータ量の目標を時間で表し、最大約 1 時間分を許容する設計を目指す"},{"id":"c","text":"パスワードを 1 時間ごとに変更する"},{"id":"d","text":"ログを 1 時間だけ保存する"}]','"b"','正解は B。RPO は復旧時点目標で、どの時点までのデータを復元できる必要があるかを表す。復旧にかかる時間を表す RTO とは異なる。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0013','exam-sg','脆弱性管理','standard','single_choice','脆弱性対応の優先順位を決める際、最も適切な考え方はどれか。',
'[{"id":"a","text":"発見順だけで対応する"},{"id":"b","text":"すべての脆弱性を同じ優先度にする"},{"id":"c","text":"深刻度、悪用状況、資産の重要性、外部公開状況などを考慮する"},{"id":"d","text":"パッチが出ていれば影響確認をせず本番へ適用する"}]','"c"','正解は C。深刻度だけでなく、実際の悪用状況、システムの重要性や露出度、対策の実現性を踏まえて優先順位を決める。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0014','exam-sg','個人情報保護','standard','single_choice','個人情報を誤送信したことに気付いた場合の初動として最も適切なものはどれか。',
'[{"id":"a","text":"送信記録を削除する"},{"id":"b","text":"組織の報告手順に従い、記録を保全して責任者に連絡する"},{"id":"c","text":"受信者の情報を公開する"},{"id":"d","text":"報告せず、受信者が気付かないことを期待する"}]','"b"','正解は B。速やかに報告し、送信内容や時刻などの記録を保全する。影響評価や受信者への連絡などは組織の手順に沿って行う。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0015','exam-sg','監査ログ','standard','single_choice','監査ログの保護策として最も適切なものはどれか。',
'[{"id":"a","text":"すべての利用者にログ削除権限を与える"},{"id":"b","text":"ログの時刻を記録し、アクセス権を制限して改ざんを検知できるようにする"},{"id":"c","text":"障害時に備えてログを記録しない"},{"id":"d","text":"ログを誰でも編集できる共有ファイルに保存する"}]','"b"','正解は B。監査ログは追跡と調査に重要なため、時刻同期、アクセス制限、保全、改ざん検知などを考慮する。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0016','exam-sg','認証','standard','single_choice','多要素認証として適切な組合せはどれか。',
'[{"id":"a","text":"パスワードと秘密の質問"},{"id":"b","text":"パスワードと登録済み端末の認証アプリが生成するコード"},{"id":"c","text":"異なる二つのパスワード"},{"id":"d","text":"ユーザー ID とメールアドレス"}]','"b"','正解は B。知識・所持・生体など異なる種類の要素を組み合わせる。パスワードと秘密の質問は通常どちらも知識要素であり、二つあっても多要素とは限らない。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0017','exam-sg','委託先管理','standard','single_choice','委託先に顧客データを取り扱わせる前に行う対応として最も適切なものはどれか。',
'[{"id":"a","text":"契約や管理策を確認せずデータを渡す"},{"id":"b","text":"委託先の安全管理、契約上の責任、アクセス範囲と監督方法を確認する"},{"id":"c","text":"委託先にすべての管理者パスワードを渡す"},{"id":"d","text":"委託した後は監督しない"}]','"b"','正解は B。委託先の管理体制、契約、取扱範囲、再委託、事故報告、監督方法などを事前に確認し、継続的に管理する。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0018','exam-sg','メールセキュリティ','standard','single_choice','不審な添付ファイルを受け取ったときの対応として最も適切なものはどれか。',
'[{"id":"a","text":"内容を確認するためすぐに開く"},{"id":"b","text":"個人メールへ転送して開く"},{"id":"c","text":"開かずに組織の手順に従って報告し、必要な分析を依頼する"},{"id":"d","text":"同僚全員に転送する"}]','"c"','正解は C。不審な添付を開いたり拡散したりせず、組織の報告手順に従う。必要な分析は承認された環境で行う。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0019','exam-sg','Webアプリケーションセキュリティ','standard','single_choice','SQL インジェクションの予防策として最も適切なものはどれか。',
'[{"id":"a","text":"入力値を SQL 文字列へ直接連結する"},{"id":"b","text":"パラメータ化クエリを使用し、必要な入力検証を行う"},{"id":"c","text":"エラーログをすべて無効化する"},{"id":"d","text":"データベースをインターネットへ直接公開する"}]','"b"','正解は B。パラメータ化クエリは入力値を SQL 構文から分離し、SQL インジェクションのリスクを下げる。単なる文字列連結は避ける。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0020','exam-sg','Webアプリケーションセキュリティ','standard','single_choice','XSS 対策として最も適切なものはどれか。',
'[{"id":"a","text":"利用者入力を適切な文脈で出力エンコードする"},{"id":"b","text":"すべての入力を HTML として実行する"},{"id":"c","text":"HTTPS だけを有効にして XSS 対策を完了とする"},{"id":"d","text":"ブラウザの更新を禁止する"}]','"a"','正解は A。HTML、属性、URL、JavaScript など出力先の文脈に合ったエンコードと、安全な API の利用が重要。HTTPS だけでは XSS を防げない。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0021','exam-sg','マルウェア対策','standard','single_choice','ランサムウェア被害からの復旧力を高める対策として最も適切なものはどれか。',
'[{"id":"a","text":"本番端末から常に書換可能なバックアップだけを持つ"},{"id":"b","text":"バックアップを定期取得し、分離・保護して復元テストを行う"},{"id":"c","text":"すべてのログを削除する"},{"id":"d","text":"全社員で管理者アカウントを共有する"}]','"b"','正解は B。バックアップを本番環境から分離・保護し、定期的に復元を試験する。常時書換可能なバックアップはランサムウェアで同時に暗号化されるおそれがある。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0022','exam-sg','クラウドセキュリティ','standard','single_choice','クラウドサービス利用時の責任共有モデルについて最も適切なものはどれか。',
'[{"id":"a","text":"クラウド事業者が利用者のすべての設定とデータを必ず管理する"},{"id":"b","text":"利用者は契約とサービス形態に応じて、データ、ID、設定など自らの責任範囲を管理する"},{"id":"c","text":"クラウド上のデータにはアクセス制御が不要である"},{"id":"d","text":"クラウドではログ監視ができない"}]','"b"','正解は B。責任範囲はサービス形態や契約によって異なる。利用者側も ID、アクセス権、データ、設定、ログなどの責任範囲を理解する必要がある。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0023','exam-sg','認可','standard','single_choice','認証と認可の違いとして最も適切なものはどれか。',
'[{"id":"a","text":"認証は本人確認、認可は許可する操作や資源の決定"},{"id":"b","text":"認証はバックアップ、認可は暗号化"},{"id":"c","text":"認証と認可は同じ意味"},{"id":"d","text":"認可は必ずパスワード変更を意味する"}]','"a"','正解は A。Authentication は誰であるかの確認、Authorization は何をしてよいかの決定。両者を混同しない。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0024','exam-sg','可用性','standard','single_choice','サービスの可用性を高める対策として最も適切なものはどれか。',
'[{"id":"a","text":"単一障害点を増やす"},{"id":"b","text":"冗長化、監視、障害時の切替手順を整備する"},{"id":"c","text":"復旧手順を文書化しない"},{"id":"d","text":"バックアップを同じ障害領域だけに保存する"}]','"b"','正解は B。冗長化、監視、切替手順、復旧訓練などにより障害時もサービスを継続・復旧しやすくする。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0025','exam-sg','変更管理','standard','single_choice','本番システムの変更管理で重要な対応として最も適切なものはどれか。',
'[{"id":"a","text":"変更内容、影響、承認、試験、ロールバック手順を記録する"},{"id":"b","text":"変更履歴を残さない"},{"id":"c","text":"誰でも直接本番変更できるようにする"},{"id":"d","text":"障害が起きても変更を戻せないようにする"}]','"a"','正解は A。変更の追跡可能性を確保し、影響評価、承認、テスト、実施計画とロールバック手順を整備する。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0026','exam-sg','ソーシャルエンジニアリング','standard','single_choice','電話で管理者を名乗る人物から認証コードを聞かれた場合、最も適切な対応はどれか。',
'[{"id":"a","text":"相手が急いでいるならコードを伝える"},{"id":"b","text":"本人確認を別の信頼できる連絡経路で行い、コードは共有せず報告する"},{"id":"c","text":"コードをメールで送る"},{"id":"d","text":"認証コードを社内チャットに投稿する"}]','"b"','正解は B。認証コードや MFA 承認を他人と共有しない。独立した信頼できる連絡経路で確認し、疑わしい要求を報告する。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0027','exam-sg','データ分類','standard','single_choice','機密情報を外部へ共有する前の対応として最も適切なものはどれか。',
'[{"id":"a","text":"共有リンクを誰でもアクセス可能にする"},{"id":"b","text":"情報分類と共有目的を確認し、承認された相手に必要最小限で安全に共有する"},{"id":"c","text":"個人用クラウドへ無断でアップロードする"},{"id":"d","text":"アクセス記録を無効にする"}]','"b"','正解は B。情報分類、共有目的、承認、相手の権限、転送方法、保管期限を確認し、必要最小限の範囲で共有する。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0028','exam-sg','情報セキュリティ管理','standard','single_choice','情報セキュリティ教育の効果を高める方法として最も適切なものはどれか。',
'[{"id":"a","text":"入社時に一度だけ資料を配る"},{"id":"b","text":"職務とリスクに応じた定期教育に加え、訓練結果を評価して改善する"},{"id":"c","text":"事故が起きても教育内容を見直さない"},{"id":"d","text":"すべての部門に同じ例だけを示し続ける"}]','"b"','正解は B。役割とリスクに合わせた継続的教育や訓練を行い、理解度・結果を測定して内容を改善する。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0029','exam-sg','内部不正対策','standard','single_choice','内部不正リスクを低減する管理策として最も適切なものはどれか。',
'[{"id":"a","text":"重要操作を一人だけが承認・実行・監査する"},{"id":"b","text":"職務分掌、権限分離、ログ監視と定期的な権限レビューを組み合わせる"},{"id":"c","text":"管理者操作のログを残さない"},{"id":"d","text":"共有アカウントを増やす"}]','"b"','正解は B。職務分掌、相互牽制、権限分離、ログ監視、権限レビューなどを組み合わせ、単独で不正を完結しにくくする。','generated','知学 自编练习题 v2','ja'),
('sg-practice-0030','exam-sg','脆弱性診断','standard','single_choice','Web アプリケーションの脆弱性診断を行う際、最も適切な準備はどれか。',
'[{"id":"a","text":"許可なく第三者の本番サイトをスキャンする"},{"id":"b","text":"対象範囲、実施時間、許可、影響と連絡先を事前に合意する"},{"id":"c","text":"診断結果を公開してから担当者へ知らせる"},{"id":"d","text":"バックアップや監視を停止する"}]','"b"','正解は B。診断は対象と権限を明確にし、影響、時間帯、監視、連絡先、復旧計画を合意して実施する。許可のない診断は行わない。','generated','知学 自编练习题 v2','ja');
